import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// The prompt texts live as Markdown next to the prompt modules so an author can read and edit them;
// the apps bundle TypeScript, so this script folds every resource into one generated module. Run it
// after editing a resource; a test fails when the generated file is stale.
const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const resourcesDirectory = path.join(repoRoot, 'packages/story-ai/src/ai/prompts/resources');
const outputFile = path.join(repoRoot, 'packages/story-ai/src/ai/prompts/resources.generated.ts');

export function renderPromptResourcesModule(directory = resourcesDirectory) {
  const files = fs
    .readdirSync(directory)
    .filter((name) => name.endsWith('.md'))
    .sort();
  const entries = files.map((name) => {
    const key = name.slice(0, -'.md'.length);
    const text = fs.readFileSync(path.join(directory, name), 'utf8');
    return `  ${JSON.stringify(key)}: ${JSON.stringify(text)},`;
  });

  return [
    '// GENERATED by scripts/build-prompt-resources.mjs from the .md files in ./resources. Do not edit.',
    '// Edit the Markdown and rerun `npm run build:prompts --workspace @storyboard/story-ai`.',
    '',
    'export const promptResourceSources: Readonly<Record<string, string>> = {',
    ...entries,
    '};',
    '',
  ].join('\n');
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  const rendered = renderPromptResourcesModule();

  if (check) {
    const current = fs.existsSync(outputFile) ? fs.readFileSync(outputFile, 'utf8') : '';
    if (current !== rendered) {
      console.error('prompt resources are stale: run npm run build:prompts --workspace @storyboard/story-ai');
      process.exit(1);
    }
    console.log('prompt resources are current');
  } else {
    fs.writeFileSync(outputFile, rendered);
    console.log(`wrote ${path.relative(repoRoot, outputFile)}`);
  }
}
